// Package litewire provides compact, reflection-free protobuf wire primitives
// for code generated by cmd/protoc-gen-go-lite.
package litewire

import (
	"errors"
	"math"
	"math/bits"
	"slices"
)

// Number represents a protobuf field number.
type Number int32

const (
	MinValidNumber Number = 1
	MaxValidNumber Number = 1<<29 - 1
)

// Type represents a protobuf wire type.
type Type int8

const (
	VarintType     Type = 0
	Fixed64Type    Type = 1
	BytesType      Type = 2
	StartGroupType Type = 3
	EndGroupType   Type = 4
	Fixed32Type    Type = 5
)

const (
	errCodeTruncated = -1
	errCodeOverflow  = -2
	errCodeReserved  = -3
	errCodeEndGroup  = -4
	errCodeRecursion = -5
)

var (
	errTruncated = errors.New("proto: cannot parse invalid wire-format data")
	errOverflow  = errors.New("proto: varint overflow")
	errReserved  = errors.New("proto: invalid field number or wire type")
	errEndGroup  = errors.New("proto: unexpected end group tag")
	errRecursion = errors.New("proto: exceeded max recursion depth")
)

// ParseError converts a negative Consume* error code into an error.
func ParseError(n int) error {
	switch n {
	case errCodeOverflow:
		return errOverflow
	case errCodeReserved:
		return errReserved
	case errCodeEndGroup:
		return errEndGroup
	case errCodeRecursion:
		return errRecursion
	default:
		return errTruncated
	}
}

func EncodeBool(x bool) uint64 {
	if x {
		return 1
	}
	return 0
}

func DecodeBool(x uint64) bool {
	return x != 0
}

func EncodeZigZag(x int64) uint64 {
	return uint64(x<<1) ^ uint64(x>>63)
}

func DecodeZigZag(x uint64) int64 {
	return int64(x>>1) ^ -int64(x&1)
}

func SizeVarint(v uint64) int {
	return (bits.Len64(v|1) + 6) / 7
}

func SizeTag(num Number) int {
	return SizeVarint(uint64(num) << 3)
}

func SizeBytes(n int) int {
	return SizeVarint(uint64(n)) + n
}

//go:noinline
func AppendRawVarint(b []byte, v uint64) []byte {
	for v >= 0x80 {
		b = append(b, byte(v)|0x80)
		v >>= 7
	}
	return append(b, byte(v))
}

func AppendTag(b []byte, num Number, typ Type) []byte {
	return AppendRawVarint(b, uint64(num)<<3|uint64(typ&7))
}

//go:noinline
func AppendRawFixed32(b []byte, v uint32) []byte {
	return append(b, byte(v), byte(v>>8), byte(v>>16), byte(v>>24))
}

//go:noinline
func AppendRawFixed64(b []byte, v uint64) []byte {
	return append(b,
		byte(v), byte(v>>8), byte(v>>16), byte(v>>24),
		byte(v>>32), byte(v>>40), byte(v>>48), byte(v>>56),
	)
}

//go:noinline
func AppendMessagePrefix(b []byte, num Number, size int) []byte {
	b = AppendTag(b, num, BytesType)
	return AppendRawVarint(b, uint64(size))
}

//go:noinline
func SizeString(num Number, v string) int {
	if v == "" {
		return 0
	}
	return SizeTag(num) + SizeBytes(len(v))
}

//go:noinline
func SizeStringAlways(num Number, v string) int {
	return SizeTag(num) + SizeBytes(len(v))
}

//go:noinline
func SizeBytesField(num Number, v []byte) int {
	if len(v) == 0 {
		return 0
	}
	return SizeTag(num) + SizeBytes(len(v))
}

//go:noinline
func SizeBytesFieldAlways(num Number, v []byte) int {
	return SizeTag(num) + SizeBytes(len(v))
}

//go:noinline
func SizeBool(num Number, v bool) int {
	if !v {
		return 0
	}
	return SizeTag(num) + 1
}

//go:noinline
func SizeBoolAlways(num Number) int {
	return SizeTag(num) + 1
}

//go:noinline
func SizeVarintField(num Number, v uint64) int {
	if v == 0 {
		return 0
	}
	return SizeTag(num) + SizeVarint(v)
}

//go:noinline
func SizeVarintFieldAlways(num Number, v uint64) int {
	return SizeTag(num) + SizeVarint(v)
}

//go:noinline
func SizeInt32(num Number, v int32) int {
	if v == 0 {
		return 0
	}
	return SizeTag(num) + SizeVarint(uint64(int64(v)))
}

//go:noinline
func SizeInt32Always(num Number, v int32) int {
	return SizeTag(num) + SizeVarint(uint64(int64(v)))
}

//go:noinline
func SizeZigZag(num Number, v int64) int {
	if v == 0 {
		return 0
	}
	return SizeTag(num) + SizeVarint(EncodeZigZag(v))
}

//go:noinline
func SizeZigZagAlways(num Number, v int64) int {
	return SizeTag(num) + SizeVarint(EncodeZigZag(v))
}

//go:noinline
func SizeFixed32(num Number, v uint32) int {
	if v == 0 {
		return 0
	}
	return SizeTag(num) + 4
}

//go:noinline
func SizeFixed32Always(num Number) int {
	return SizeTag(num) + 4
}

//go:noinline
func SizeFixed64(num Number, v uint64) int {
	if v == 0 {
		return 0
	}
	return SizeTag(num) + 8
}

//go:noinline
func SizeFixed64Always(num Number) int {
	return SizeTag(num) + 8
}

//go:noinline
func SizeFloat(num Number, v float32) int {
	if v == 0 {
		return 0
	}
	return SizeTag(num) + 4
}

//go:noinline
func SizeDouble(num Number, v float64) int {
	if v == 0 {
		return 0
	}
	return SizeTag(num) + 8
}

//go:noinline
func SizeMessage(num Number, bodySize int) int {
	return SizeTag(num) + SizeBytes(bodySize)
}

//go:noinline
func AppendString(b []byte, num Number, v string) []byte {
	if v == "" {
		return b
	}
	return AppendStringAlways(b, num, v)
}

//go:noinline
func AppendStringAlways(b []byte, num Number, v string) []byte {
	b = AppendTag(b, num, BytesType)
	b = AppendRawVarint(b, uint64(len(v)))
	return append(b, v...)
}

//go:noinline
func AppendBytes(b []byte, num Number, v []byte) []byte {
	if len(v) == 0 {
		return b
	}
	return AppendBytesAlways(b, num, v)
}

//go:noinline
func AppendBytesAlways(b []byte, num Number, v []byte) []byte {
	b = AppendTag(b, num, BytesType)
	b = AppendRawVarint(b, uint64(len(v)))
	return append(b, v...)
}

//go:noinline
func AppendBool(b []byte, num Number, v bool) []byte {
	if !v {
		return b
	}
	return AppendBoolAlways(b, num, v)
}

//go:noinline
func AppendBoolAlways(b []byte, num Number, v bool) []byte {
	b = AppendTag(b, num, VarintType)
	return AppendRawVarint(b, EncodeBool(v))
}

//go:noinline
func AppendVarint(b []byte, num Number, v uint64) []byte {
	if v == 0 {
		return b
	}
	return AppendVarintAlways(b, num, v)
}

//go:noinline
func AppendVarintAlways(b []byte, num Number, v uint64) []byte {
	b = AppendTag(b, num, VarintType)
	return AppendRawVarint(b, v)
}

