//go:noinline
func AppendZigZag(b []byte, num Number, v int64) []byte {
	if v == 0 {
		return b
	}
	return AppendVarintAlways(b, num, EncodeZigZag(v))
}

//go:noinline
func AppendZigZagAlways(b []byte, num Number, v int64) []byte {
	return AppendVarintAlways(b, num, EncodeZigZag(v))
}

//go:noinline
func AppendFixed32(b []byte, num Number, v uint32) []byte {
	if v == 0 {
		return b
	}
	return AppendFixed32Always(b, num, v)
}

